  type CalculatorTerms={dice:Array<{count:number;sides:number}>;flat:number};
  const calculatorBandValue=(bands:any[],level:number):number=>Number(bands.find((band:any)=>level>=band.minimum_level&&level<=band.maximum_level)?.value??0);
  const calculatorTierMinimum=(tier:number):number=>Number(calculator.tier_minimum_levels.find((item:any)=>item.tier===tier)?.minimum_level??calculator.fighter_level_minimum);
  const calculatorSelectionAvailable=(selection:string):boolean=>calculatorCardIdSet.has(selection);
  const calculatorSelectionInGroup=(selection:string,group=state.calculatorFeatureGroup):boolean=>group===""||calculatorCardArea(selection)===group;
  const calculatorValues=()=>{const proficiencyBonus=calculatorBandValue(calculator.proficiency_bonus_bands,state.fighterLevel),totalPsiPoints=calculatorBandValue(calculator.psi_point_bands,state.fighterLevel),psionicFocus=calculatorBandValue(calculator.psionic_focus_bands,state.fighterLevel),strikeSides=calculatorBandValue(calculator.manifested_strike_die_bands,state.fighterLevel),attackBonus=proficiencyBonus+state.psiModifier+psionicFocus,saveDc=8+proficiencyBonus+state.psiModifier;return{proficiencyBonus,totalPsiPoints,psionicFocus,strikeSides,attackBonus,saveDc,strike:{dice:[{count:1,sides:strikeSides}],flat:state.psiModifier} as CalculatorTerms};};
  const calculatorDamageTerms=(damage:any,strikeSides:number):CalculatorTerms=>{if(damage.kind==="fixed")return{dice:[],flat:damage.value};if(damage.kind==="dice")return{dice:[{count:damage.count,sides:damage.sides}],flat:0};if(damage.kind==="manifested_strike_dice")return{dice:[{count:damage.count,sides:strikeSides}],flat:0};if(damage.kind==="psionic_ability_modifier")return{dice:[],flat:state.psiModifier*Number(damage.multiplier??1)};return{dice:[],flat:0};};
