  function formatCalculatorDamage(terms:CalculatorTerms):string {const dice=new Map<number,number>();for(const term of terms.dice)dice.set(term.sides,(dice.get(term.sides)??0)+term.count);const expression=[...dice].map(([sides,count])=>`${count}d${sides}`).join(" + ");if(!expression)return String(terms.flat);if(terms.flat===0)return expression;return `${expression} ${terms.flat<0?"-":"+"} ${Math.abs(terms.flat)}`;}
  const calculatorHitCalculation=(values:ReturnType<typeof calculatorValues>):string=>`1d20 + Proficiency Bonus (${values.proficiencyBonus}) + Psionic Ability Modifier (${state.psiModifier}) + Psionic Focus (${values.psionicFocus}) = 1d20 + ${values.attackBonus}`;
  const calculatorDamageCalculation=(values:ReturnType<typeof calculatorValues>):string=>`Manifested Strike die (1d${values.strikeSides}) + Psionic Ability Modifier (${state.psiModifier}) = ${formatCalculatorDamage(values.strike)}`;
  const calculatorSaveCalculation=(values:ReturnType<typeof calculatorValues>):string=>`8 + Proficiency Bonus (${values.proficiencyBonus}) + Psionic Ability Modifier (${state.psiModifier}) = ${values.saveDc}`;
  const calculatorAverage=(terms:CalculatorTerms):number=>terms.dice.reduce((total,term)=>total+term.count*(term.sides+1)/2,terms.flat);
