  function appendProjectionMetric(parent:HTMLElement,metric:any,values:ReturnType<typeof calculatorValues>,tier?:number):void {const label=String(ui.get(`calculator_metric_${metric.label}`));if(metric.kind==="fixed_plus_proficiency_bonus_multiplier"){const authored=metric.values.find((item:any)=>item.tier===tier);if(!authored)return;const result=authored.fixed+authored.multiplier*values.proficiencyBonus,unit=String(ui.get(`calculator_unit_${metric.unit}`));appendCalculatorMetric(parent,label,`${result} ${unit}`);if(authored.multiplier)appendCalculatorMetric(parent,String(ui.get("calculator_calculation_label")),`${authored.fixed} + (${authored.multiplier} × Proficiency Bonus ${values.proficiencyBonus}) = ${result} ${unit}`,"calculator__calculation");return;}if(tier!==undefined)return;if(metric.kind==="floor_proficiency_bonus_divisor"){const result=Math.floor(values.proficiencyBonus/metric.divisor);appendCalculatorMetric(parent,label,String(result));appendCalculatorMetric(parent,String(ui.get("calculator_calculation_label")),`floor(Proficiency Bonus ${values.proficiencyBonus} ÷ ${metric.divisor}) = ${result}`,"calculator__calculation");return;}if(metric.kind==="psionic_ability_modifier_multiplier"){const result=state.psiModifier*metric.multiplier;appendCalculatorMetric(parent,label,`+${result}`);appendCalculatorMetric(parent,String(ui.get("calculator_calculation_label")),`${metric.multiplier} × Psionic Ability Modifier (${state.psiModifier}) = ${result}`,"calculator__calculation");return;}if(metric.kind==="dice_plus_psionic_ability_modifier"){return;}if(metric.kind==="psi_points_plus_fixed"){const result=values.totalPsiPoints+metric.value;appendCalculatorMetric(parent,label,String(result));appendCalculatorMetric(parent,String(ui.get("calculator_calculation_label")),`Base Psi Points (${values.totalPsiPoints}) + ${metric.value} = ${result}`,"calculator__calculation");}}
